//! Local PTY lifecycle and terminal protocol, independent of T3 and pane navigation.
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use portable_pty::{CommandBuilder, MasterPty, PtySize};
use std::{
    io::{Read, Write},
    sync::{Arc, Mutex, mpsc},
};

/// Replies are generated by the parser at the query's position in the stream,
/// including when an escape sequence spans multiple PTY reads.
#[derive(Default)]
pub struct TerminalReplies {
    pending: Vec<Vec<u8>>,
}
impl vt100::Callbacks for TerminalReplies {
    fn unhandled_csi(
        &mut self,
        screen: &mut vt100::Screen,
        prefix: Option<u8>,
        _: Option<u8>,
        params: &[&[u16]],
        c: char,
    ) {
        let p = params.first().and_then(|p| p.first()).copied().unwrap_or(0);
        let reply = match (prefix, c, p) {
            (None, 'c', 0) => "\x1b[?1;2c".to_owned(),
            (Some(b'>'), 'c', 0) => "\x1b[>0;1;0c".to_owned(),
            (None, 'n', 5) => "\x1b[0n".to_owned(),
            (None | Some(b'?'), 'n', 6) => {
                let (row, col) = screen.cursor_position();
                format!(
                    "\x1b[{}{};{}R",
                    if prefix.is_some() { "?" } else { "" },
                    row + 1,
                    col + 1
                )
            }
            (None, 't', 18) => {
                let (rows, cols) = screen.size();
                format!("\x1b[8;{rows};{cols}t")
            }
            // Report legacy keyboard input, without enabling an unsupported protocol.
            (Some(b'?'), 'u', _) => "\x1b[?0u".to_owned(),
            (Some(b'>'), 'q', _) => "\x1bP>|tui3\x1b\\".to_owned(),
            _ => return,
        };
        self.pending.push(reply.into_bytes());
    }
    fn unhandled_osc(&mut self, _: &mut vt100::Screen, params: &[&[u8]]) {
        if let [kind @ (b"10" | b"11"), b"?"] = params {
            let color = if *kind == b"10" {
                "dddd/dddd/dddd"
            } else {
                "0000/0000/0000"
            };
            self.pending.push(
                format!("\x1b]{};rgb:{color}\x1b\\", String::from_utf8_lossy(kind)).into_bytes(),
            );
        }
    }
}

#[derive(Default)]
pub struct LocalTerminal {
    pub session: Option<Session>,
    pub error: Option<String>,
}
pub struct Session {
    pub parser: Arc<Mutex<vt100::Parser<TerminalReplies>>>,
    master: Box<dyn MasterPty + Send>,
    child: Box<dyn portable_pty::Child + Send + Sync>,
    input: mpsc::SyncSender<Vec<u8>>,
    size: (u16, u16),
    pub cwd: String,
    pub status: Arc<Mutex<Option<String>>>,
}
impl Session {
    pub fn start(cwd: String) -> Result<Self, String> {
        Self::start_shell(
            cwd,
            std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".into()),
        )
    }
    pub(crate) fn start_shell(cwd: String, shell: String) -> Result<Self, String> {
        let pair = portable_pty::native_pty_system()
            .openpty(PtySize {
                rows: 24,
                cols: 80,
                pixel_width: 0,
                pixel_height: 0,
            })
            .map_err(|e| e.to_string())?;
        let mut cmd = CommandBuilder::new(shell);
        cmd.cwd(&cwd);
        cmd.env("TERM", "xterm-256color");
        let mut reader = pair.master.try_clone_reader().map_err(|e| e.to_string())?;
        let mut writer = pair.master.take_writer().map_err(|e| e.to_string())?;
        let child = pair.slave.spawn_command(cmd).map_err(|e| e.to_string())?;
        drop(pair.slave);
        let parser = Arc::new(Mutex::new(vt100::Parser::new_with_callbacks(
            24,
            80,
            10_000,
            TerminalReplies::default(),
        )));
        let status = Arc::new(Mutex::new(None));
        let (input, receive) = mpsc::sync_channel::<Vec<u8>>(256);
        let replies = input.clone();
        let output_parser = parser.clone();
        let output_status = status.clone();
        std::thread::spawn(move || {
            let mut buf = [0; 8192];
            loop {
                match reader.read(&mut buf) {
                    Ok(0) => {
                        *output_status.lock().unwrap() =
                            Some("Shell exited. Close and reopen to restart.".into());
                        break;
                    }
                    Ok(n) => {
                        let mut parser = output_parser.lock().unwrap();
                        parser.process(&buf[..n]);
                        let responses = std::mem::take(&mut parser.callbacks_mut().pending);
                        drop(parser);
                        for response in responses {
                            if replies.send(response).is_err() {
                                return;
                            }
                        }
                    }
                    Err(e) => {
                        *output_status.lock().unwrap() = Some(format!("Terminal closed: {e}"));
                        break;
                    }
                }
            }
        });
        let write_status = status.clone();
        std::thread::spawn(move || {
            while let Ok(bytes) = receive.recv() {
                if let Err(e) = writer.write_all(&bytes).and_then(|_| writer.flush()) {
                    *write_status.lock().unwrap() = Some(format!("Terminal input failed: {e}"));
                    break;
                }
            }
        });
        Ok(Self {
            parser,
            master: pair.master,
            child,
            input,
            size: (24, 80),
            cwd,
            status,
        })
    }
    pub fn send(&self, bytes: Vec<u8>) {
        if let Err(e) = self.input.try_send(bytes) {
            *self.status.lock().unwrap() = Some(format!("Terminal input unavailable: {e}"));
        }
    }
    pub fn paste(&self, text: &str) {
        let text = text.replace('\x1b', "");
        let bracketed = self.parser.lock().unwrap().screen().bracketed_paste();
        self.send(if bracketed {
            format!("\x1b[200~{text}\x1b[201~").into_bytes()
        } else {
            text.into_bytes()
        });
    }
    pub fn resize(&mut self, rows: u16, cols: u16) {
        let size = (rows.max(1), cols.max(1));
        if size == self.size {
            return;
        }
        if let Err(e) = self.master.resize(PtySize {
            rows: size.0,
            cols: size.1,
            pixel_width: 0,
            pixel_height: 0,
        }) {
            *self.status.lock().unwrap() = Some(format!("Terminal resize failed: {e}"));
            return;
        }
        self.parser
            .lock()
            .unwrap()
            .screen_mut()
            .set_size(size.0, size.1);
        self.size = size;
    }
    pub fn scroll(&self, delta: isize) {
        let mut parser = self.parser.lock().unwrap();
        let offset = parser.screen().scrollback().saturating_add_signed(delta);
        parser.screen_mut().set_scrollback(offset);
    }
}
impl Drop for Session {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}
pub fn key_bytes(key: KeyEvent, application: bool) -> Vec<u8> {
    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
    let mut bytes = match key.code {
        KeyCode::Char(c) if ctrl && c.is_ascii() => vec![(c.to_ascii_uppercase() as u8) & 0x1f],
        KeyCode::Char(c) => c.to_string().into_bytes(),
        KeyCode::Enter => vec![b'\r'],
        KeyCode::Tab => vec![b'\t'],
        KeyCode::BackTab => b"\x1b[Z".to_vec(),
        KeyCode::Backspace => vec![127],
        KeyCode::Esc => vec![27],
        KeyCode::Up
        | KeyCode::Down
        | KeyCode::Right
        | KeyCode::Left
        | KeyCode::Home
        | KeyCode::End => {
            let end = match key.code {
                KeyCode::Up => 'A',
                KeyCode::Down => 'B',
                KeyCode::Right => 'C',
                KeyCode::Left => 'D',
                KeyCode::Home => 'H',
                _ => 'F',
            };
            let modifier = 1
                + u8::from(key.modifiers.contains(KeyModifiers::SHIFT))
                + 2 * u8::from(key.modifiers.contains(KeyModifiers::ALT))
                + 4 * u8::from(ctrl);
            if modifier > 1 {
                return format!("\x1b[1;{modifier}{end}").into_bytes();
            }
            format!("\x1b{}{end}", if application { 'O' } else { '[' }).into_bytes()
        }
        KeyCode::Delete => b"\x1b[3~".to_vec(),
        KeyCode::Insert => b"\x1b[2~".to_vec(),
        KeyCode::PageUp => b"\x1b[5~".to_vec(),
        KeyCode::PageDown => b"\x1b[6~".to_vec(),
        KeyCode::F(n @ 1..=4) => vec![27, b'O', b'P' + n - 1],
        KeyCode::F(n @ 5..=12) => format!(
            "\x1b[{}~",
            [15, 17, 18, 19, 20, 21, 23, 24][(n - 5) as usize]
        )
        .into_bytes(),
        _ => return Vec::new(),
    };
    if key.modifiers.contains(KeyModifiers::ALT) {
        bytes.insert(0, 27);
    }
    bytes
}

#[cfg(test)]
mod tests {
    use super::*;
    fn wait_for(session: &Session, needle: &str) {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            let contents = session.parser.lock().unwrap().screen().contents();
            if contents.contains(needle) {
                return;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "missing {needle:?}: {contents:?}"
            );
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
    }
    #[test]
    fn fish_accepts_input_after_capability_negotiation() {
        if !std::path::Path::new("/usr/bin/fish").exists() {
            return;
        }
        let session = Session::start_shell("/tmp".into(), "/usr/bin/fish".into()).unwrap();
        // Fish blocks at startup without a primary device attributes response.
        session.send(b"printf 'fish_%s_ready\\n' input\r".to_vec());
        wait_for(&session, "fish_input_ready");
        session.send(b"sleep 30\r".to_vec());
        std::thread::sleep(std::time::Duration::from_millis(100));
        session.send(vec![3]);
        session.send(b"printf 'interrupt_%s_ok\\n' works\r".to_vec());
        wait_for(&session, "interrupt_works_ok");
    }
    #[test]
    fn interactive_pager_accepts_navigation_and_returns_to_shell() {
        if !std::path::Path::new("/usr/bin/less").exists() {
            return;
        }
        let dir = tempfile::tempdir().unwrap();
        let content = (0..100)
            .map(|i| format!("pager_line_{i:03}\n"))
            .collect::<String>();
        std::fs::write(dir.path().join("pager.txt"), content).unwrap();
        let mut session =
            Session::start_shell(dir.path().to_string_lossy().into_owned(), "/bin/sh".into())
                .unwrap();
        session.resize(12, 60);
        session.send(b"less pager.txt\r".to_vec());
        wait_for(&session, "pager_line_000");
        assert!(session.parser.lock().unwrap().screen().alternate_screen());
        session.send(key_bytes(
            KeyEvent::new(KeyCode::Char('G'), KeyModifiers::SHIFT),
            false,
        ));
        wait_for(&session, "pager_line_099");
        session.send(b"q".to_vec());
        session.send(b"printf 'pager_%s_ok\\n' exit\r".to_vec());
        wait_for(&session, "pager_exit_ok");
        assert!(!session.parser.lock().unwrap().screen().alternate_screen());
    }
    #[test]
    fn query_replies_are_fragment_safe_ordered_and_do_not_match_plain_text() {
        let mut parser = vt100::Parser::new_with_callbacks(24, 80, 0, TerminalReplies::default());
        for byte in b"\x1b[0c\x1b[3;7H\x1b[6n\x1b[H\x1b[6n\x1b[5n\x1b[?u" {
            parser.process(&[*byte]);
        }
        assert_eq!(
            parser.callbacks().pending,
            [
                b"\x1b[?1;2c".to_vec(),
                b"\x1b[3;7R".to_vec(),
                b"\x1b[1;1R".to_vec(),
                b"\x1b[0n".to_vec(),
                b"\x1b[?0u".to_vec()
            ]
        );
        parser.callbacks_mut().pending.clear();
        parser.process(b"[6n [0c");
        assert!(parser.callbacks().pending.is_empty());
    }
    #[test]
    fn alternate_screen_restores_shell_and_preserves_color() {
        let mut parser = vt100::Parser::new(24, 80, 100);
        parser.process(b"shell\x1b[?1049h\x1b[2J\x1b[H\x1b[31mfullscreen");
        assert!(parser.screen().alternate_screen());
        assert_eq!(
            parser.screen().cell(0, 0).unwrap().fgcolor(),
            vt100::Color::Idx(1)
        );
        parser.process(b"\x1b[?1049l");
        assert!(!parser.screen().alternate_screen());
        assert_eq!(parser.screen().contents(), "shell");
    }
    #[test]
    fn terminal_keys_preserve_shell_controls() {
        for (code, modifiers, expected) in [
            (
                KeyCode::Char('c'),
                KeyModifiers::CONTROL,
                b"\x03".as_slice(),
            ),
            (KeyCode::Esc, KeyModifiers::NONE, b"\x1b".as_slice()),
            (KeyCode::Char('T'), KeyModifiers::SHIFT, b"T".as_slice()),
            (
                KeyCode::Left,
                KeyModifiers::CONTROL,
                b"\x1b[1;5D".as_slice(),
            ),
        ] {
            assert_eq!(key_bytes(KeyEvent::new(code, modifiers), false), expected);
        }
        assert_eq!(
            key_bytes(KeyEvent::new(KeyCode::Up, KeyModifiers::NONE), true),
            b"\x1bOA"
        );
    }
    #[test]
    fn real_shell_output_resize_and_scrollback() {
        let mut session = Session::start_shell(
            std::env::current_dir()
                .unwrap()
                .to_string_lossy()
                .into_owned(),
            "/bin/sh".into(),
        )
        .unwrap();
        session.resize(12, 60);
        session.send(b"printf '\\033[31mterminal_%s_ok\\033[0m\\n' smoke\r".to_vec());
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            let contents = session.parser.lock().unwrap().screen().contents();
            if contents.contains("terminal_smoke_ok") {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "shell output missing: {contents}"
            );
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        assert_eq!(session.parser.lock().unwrap().screen().size(), (12, 60));
        session.scroll(10);
        session.scroll(-10);
    }
}
